const inputData = $input.first().json || {};
const originalContext = $('Parse AI Response').first().json;

// Check if this is a chat response
if (inputData.intent === 'chat' || originalContext.intent === 'chat') {
  console.log('Processing chat response');
  const chatResponse = inputData.params?.response || inputData.response || originalContext.params?.response || originalContext.response || 'Chat response received';

  return {
    json: {
      chatId: originalContext.chatId || inputData.chatId || 'unknown',
      text: chatResponse,
      conversationHistory: originalContext.conversationHistory || inputData.conversationHistory || [],
      executionResult: { type: 'chat', response: chatResponse }
    }
  };
}

let intentData = originalContext;
let data = Array.isArray(inputData) ? inputData[0] : inputData;
let executionResult = data.executionResult || data;

let finalMessage = executionResult.response || 'Task completed!';

// Handle error - CHECK FIRST before checking for success
if (data.success === false && data.error) {
  // Error response from API
  finalMessage = data.error.trim();
} else if (executionResult.error) {
  // Error in executionResult
  let errorMessage = '';

  if (executionResult.error.message) {
    let message = executionResult.error.message;

    try {
      message = message.replace(/^\d{3}\s*-\s*/, '').trim();

      if (message.startsWith('"') && message.endsWith('"')) {
        message = message.slice(1, -1);
      }

      const firstUnescape = JSON.parse('"' + message + '"');
      const errorObj = JSON.parse(firstUnescape);

      errorMessage = errorObj.error 
        ? errorObj.error.replace(/\n/g, ' ').trim()
        : message;
    } catch (e) {
      errorMessage = executionResult.error.message || message;
    }
  }

  if (errorMessage) {
    finalMessage = errorMessage;
  }
} else if (executionResult.message) {
  finalMessage += `\n\n${executionResult.message}`;
}

// Format specific intents (only if not an error)
if (data.success !== false) {
  if (intentData.intent === 'stats' && executionResult.position) {
    finalMessage = `Position: x:${executionResult.position.x?.toFixed(1)}, y:${executionResult.position.y?.toFixed(1)}, z:${executionResult.position.z?.toFixed(1)}\nHealth: ${executionResult.health}/20\nHunger: ${executionResult.hunger}/20\nAction: ${executionResult.current_action || 'Idle'}`;
  } else if (intentData.intent === 'inventory' && executionResult.inventory) {
    const items = Array.isArray(executionResult.inventory) ? 
      executionResult.inventory.map(item => `${item.name}(${item.count})`).join(', ') : 
      'Empty';
    finalMessage = `Inventory: ${items}`;
  } else if (intentData.intent === 'nearbyBlocks' && executionResult.nearby_blocks) {
    finalMessage = `Nearby blocks: ${executionResult.nearby_blocks}`;
  } else if (intentData.intent === 'entities' && executionResult.nearby_entities) {
    finalMessage = `Nearby entities: ${executionResult.nearby_entities}`;
  } else if (intentData.intent === 'craftable' && executionResult.craftable_items) {
    finalMessage = `Craftable items: ${executionResult.craftable_items}`;
  } else if (intentData.intent === 'modes' && executionResult.modes) {
    finalMessage = `Bot modes: ${executionResult.modes}`;
  } else if (intentData.intent === 'savedPlaces' && executionResult.saved_places) {
    finalMessage = `Saved places: ${executionResult.saved_places}`;
  } else if (intentData.intent === 'getCraftingPlan' && executionResult.crafting_plan) {
    finalMessage = `Crafting plan: ${executionResult.crafting_plan}`;
  } else if (intentData.intent === 'lookAtPlayer' && executionResult.vision_result) {
    finalMessage = `Vision: ${executionResult.vision_result}`;
  } else if (intentData.intent === 'lookAtPosition' && executionResult.vision_result) {
    finalMessage = `Vision: ${executionResult.vision_result}`;
  } else if (intentData.intent === 'collaborativeBuild' && executionResult.aiActions) {
    finalMessage = `Building completed: Collaborative Build Actions:\n\n${executionResult.aiActions}`;
  }
}

const conversationHistory = intentData.conversationHistory || [];
conversationHistory.push({
  role: 'assistant',
  content: finalMessage,
  timestamp: Date.now()
});

if (conversationHistory.length > 20) {
  conversationHistory.splice(0, conversationHistory.length - 20);
}

let chatId =
  inputData.chatId ||
  intentData.chatId ||
  originalContext.chatId ||
  $('Normalize Input').first().json.chatId ||
  inputData.conversationId ||
  'unknown';

console.log('Resolved chatId:', chatId);

return {
  json: {
    chatId,
    text: finalMessage,
    conversationHistory,
    executionResult
  }
};

const aiResponse = $input.first().json;
let outputString = aiResponse.output;

console.log('Raw output:', outputString);

// Remove markdown code blocks if present
const jsonMatch = outputString.match(/```(?:json)?\n?([\s\S]*?)\n?```/);
if (jsonMatch) {
  outputString = jsonMatch[1];
  console.log('Extracted JSON from markdown');
}

let parsedIntent = null;
let parsedParams = {};
let needsClarification = false;
let clarificationQuestion = '';
let conversationState = 'executing';
let clarificationCount = 0;
let parsedResponse = null;

try {
  parsedResponse = JSON.parse(outputString);
  console.log('Parsed successfully:', parsedResponse);

  parsedIntent = parsedResponse.intent || 'chat';
  parsedParams = parsedResponse.params || parsedResponse.parameters || {};

  // Check if AI needs clarification
  if (parsedResponse.needsClarification || parsedResponse.clarification) {
    needsClarification = true;
    clarificationQuestion = parsedResponse.clarificationQuestion || 'Could you provide more details?';
    conversationState = 'clarifying';
  }
} catch (e) {
  console.log('Failed to parse, treating as chat:', e.message);
  parsedIntent = 'chat';
  parsedParams = { response: outputString };
  parsedResponse = { intent: 'chat', response: outputString };
}

return {
  json: {
    chatId: $('Telegram Bot').first().json.message.chat.id,
    conversationId: $('Telegram Bot').first().json.message.chat.id,
    botstatus: $('Get Bot Status').first().json,
    botInventory: $('Prepare Conversation Context').first().json.botInventory,
    workers: $('Prepare Conversation Context').first().json.workers,
    nearbyPlayers: $('Prepare Conversation Context').first().json.nearbyPlayers,

    username: $('Telegram Bot').first().json.message.from.username,
    intent: parsedIntent,
    params: parsedParams,
    response: parsedParams.response || outputString,
    needsClarification,
    clarificationQuestion,
    conversationState,
    clarificationCount,
    originalResponse: outputString,
    aiResponse: parsedResponse,
    parsedSuccessfully: !!parsedIntent
  }
};

const input = $input.first().json;

// Get conversation data from the previous Load Conversation History node
const conversation = input.conversation || {};
const turns = input.conversationHistory || [];
const memory = input.memory || '';


// Use current data with fallback to stored data
const botStatus = input.botStatus || {};
const botInventory = input.botInventory || [];
const worldInfo = input.worldInfo || {};
const nearbyPlayers = input.nearbyPlayers || [];
const workers = input.workers || [];

const playerName = input.playerName || 'Player';
const message = input.message || '';

// Enhanced context building from database
const conversationState = input.conversationState || 'initial';
const needsClarification = input.needsClarification || false;
const clarificationCount = input.clarificationCount || 0;



// Build comprehensive system prompt matching codebase capabilities
const promptRow = $('Get Prompts').all().find(row => row.json.agent === "Oracle").json.system_prompt;
let systemPrompt = promptRow.replaceAll('{{playerName}}', playerName);

// Add current bot status to system prompt
if (botStatus && Object.keys(botStatus).length > 0) {
  let statusText = 'Name :' + botStatus.name;
  if (botStatus.position) {
    statusText += `\nPosition: x:${botStatus.position.x?.toFixed(1)}, y:${botStatus.position.y?.toFixed(1)}, z:${botStatus.position.z?.toFixed(1)} | Health: ${botStatus.health}/20 | Action: ${botStatus.current_action || 'Idle'}`;
  }
  systemPrompt += `\n\Leader Info: ${statusText}`;
}

// Add inventory info if available
if (botInventory && Array.isArray(botInventory) && botInventory.length > 0) {
  const inventoryText = botInventory.map(item => `${item.name || item.type}(${item.count || item.quantity || 1})`).join(', ');
  systemPrompt += `\nCurrent Inventory: ${inventoryText}`;
} else {
  systemPrompt += `\nCurrent Inventory: Empty (Creative Mode)`;
}
// Add game mode info
if (botStatus && botStatus.gamemode) {
  systemPrompt += `\nGame Mode: ${botStatus.gamemode}`;
  if (botStatus.gamemode === 'creative') {
    systemPrompt += ` - You have unlimited resources and can craft/place anything without gathering materials.`;
  }
}




// Add nearby players info
if (nearbyPlayers && nearbyPlayers.length > 0) {
  systemPrompt += `\nNearby Players: ${nearbyPlayers.join(', ')}`;
} else {
  systemPrompt += `\nNearby Players: None detected`;
}

// Add orchestration workers info
if (workers && workers.length > 0) {
  systemPrompt += `\nWorkers: ${workers}.join(', ')}`;
} else {
  systemPrompt += `\nNo workers detected`;
}

// Add conversation memory if available
if (memory.trim()) {
  systemPrompt += `\n\nConversation Memory: ${memory}`;
}

// Add clarification context if in clarification state
if (conversationState === 'clarifying') {
  systemPrompt += `\n\nIMPORTANT: You are currently in clarification mode (attempt ${clarificationCount + 1}/3). The user's previous request needed more details. Based on their response, either:
1. If you now have enough information, proceed with the appropriate intent
2. If still unclear, ask ONE specific clarifying question
3. If this is attempt 3, proceed with best effort using available information`;
}

// Build messages array following codebase History.getHistory() pattern
const messages = [];

// Add enhanced system message
messages.push({
  role: 'system',
  content: systemPrompt
});

// Add conversation history - smart context management
const maxContextTurns = 15; // Increased from 10 for better context
let contextTurns = turns.slice(-maxContextTurns);

// If we have memory but limited context, add a memory summary message
if (turns.length > maxContextTurns && memory.trim()) {
  messages.push({
    role: 'system',
    content: `Previous conversation summary: ${memory}`
  });
}

// Add recent conversation turns
for (const turn of contextTurns) {
  // Ensure proper role mapping
  let role = 'user';
  if (turn.role === 'assistant' || turn.role === 'bot') {
    role = 'assistant';
  } else if (turn.role === 'system') {
    role = 'system';
  }

  messages.push({
    role: role,
    content: turn.content || turn.message || ''
  });
}

// Add current user message if not already in recent history
const recentMessages = contextTurns.slice(-3);
const alreadyIncluded = recentMessages.some(turn => 
  turn.content === message || turn.content === `${playerName}: ${message}`
);

if (!alreadyIncluded && message) {
  messages.push({
    role: 'user', 
    content: `${playerName}: ${message}`
  });
}

// Log comprehensive context info
console.log('Enhanced conversation context prepared:', {
  totalTurns: turns.length,
  contextTurns: contextTurns.length,
  messagesCount: messages.length,
  hasMemory: !!memory,
  conversationState,
  needsClarification,
  clarificationCount,
  playerName,
  currentMessage: message,
  hasStatus: !!botStatus.position,
  hasInventory: !!botInventory?.length,
  nearbyPlayersCount: (nearbyPlayers || []).length,
  mongoDataReceived: !!conversation._id,
  conversationExists: !!conversation.conversationId
});

return {
  json: {
    // Original data
    ...input,
    // MongoDB conversation data
    conversation: conversation,
    turns: turns,
    //memory: memory,
    // Merged current data
    botStatus: botStatus,
    botInventory: botInventory,
    worldInfo: worldInfo,
    nearbyPlayers: nearbyPlayers,
    // AI context
    //messages,
    conversationTurns: turns.length,
    conversationState,
    needsClarification,
    clarificationCount,
    systemPrompt,
    // Player info
    playerName: playerName,
    message: message,
    // Meta
    enhanced: true,
    dataComplete: true
  }
};

const playersHttpResponse = $('Get Nearby Players').first().json;
const workersData = $('Orchestration Status1').first().json;
const mergedData = $('Merge Status + Inventory').first().json;


// Get nearby players data from the HTTP response
let nearbyPlayers = [];
if (playersHttpResponse && playersHttpResponse.nearby_entities) {
  const entitiesText = playersHttpResponse.nearby_entities;
  console.log('Entities text:', entitiesText);

  // Extract player names from entities text
  const playerMatches = entitiesText.match(/player:\s*([\w]+)/g);
  if (playerMatches) {
    nearbyPlayers = playerMatches.map(match => match.replace('player: ', ''));
  }
}

console.log('Nearby players found:', nearbyPlayers);

// Final result with all data properly merged
const result = {
  ...mergedData,
  nearbyPlayers: nearbyPlayers,
  workers: workersData.workers,
  source: 'inventory_and_players',
  timestamp: new Date().getTime()
};


return { json: result };

const inventoryHttpResponse = $input.first().json;
const statusData = $('Merge Status Data').first().json;

console.log('=== MERGE STATUS + INVENTORY ===');
console.log('Status data:', statusData);
console.log('Inventory response:', JSON.stringify(inventoryHttpResponse, null, 2));

// Get the actual in-game player name from bot status, not telegram username
let playerName = statusData.playerName; 
// Process inventory data from API response - handle creative mode format
let botInventory = [];
console.log('Processing inventory response...');

if (inventoryHttpResponse) {
  // Handle array response format
  if (Array.isArray(inventoryHttpResponse)) {
    console.log('Inventory is array format');

    for (const item of inventoryHttpResponse) {
      if (item && item.inventory) {
        // Parse inventory text format
        const inventoryText = item.inventory;
        console.log('Parsing inventory text:', inventoryText);

        // Extract items from inventory text
        // Format: "- glass: 1" or "- item_name: quantity"
        const itemMatches = inventoryText.match(/- ([^:]+): (\d+)/g);
        if (itemMatches) {
          for (const match of itemMatches) {
            const parts = match.replace('- ', '').split(': ');
            if (parts.length === 2) {
              botInventory.push({
                name: parts[0].trim(),
                count: parseInt(parts[1]),
                type: parts[0].trim()
              });
            }
          }
        }

        // Check if creative mode
        if (inventoryText.includes('creative mode')) {
          console.log('Bot is in creative mode - unlimited items available');
        }
      }
    }
  } else if (inventoryHttpResponse.inventory) {
    // Direct inventory property
    if (Array.isArray(inventoryHttpResponse.inventory)) {
      botInventory = inventoryHttpResponse.inventory;
    } else if (typeof inventoryHttpResponse.inventory === 'string') {
      // Parse string format
      const inventoryText = inventoryHttpResponse.inventory;
      const itemMatches = inventoryText.match(/- ([^:]+): (\d+)/g);
      if (itemMatches) {
        for (const match of itemMatches) {
          const parts = match.replace('- ', '').split(': ');
          if (parts.length === 2) {
            botInventory.push({
              name: parts[0].trim(),
              count: parseInt(parts[1]),
              type: parts[0].trim()
            });
          }
        }
      }
    }
  }
}

console.log('Processed inventory:', botInventory);
console.log('Inventory count:', botInventory.length);
console.log('Using player name:', playerName);

// Merge all data together
const result = {
  ...statusData,
  playerName: playerName, // Override with in-game name
  botInventory: botInventory,
  inventoryProcessed: true
};

return { json: result };

// === MERGE STATUS DATA ===
const inputData = $('Normalize Input').first().json;
const playerData = $('Get Leader').first().json;
const worldData = $("Get World Info").first().json;
const statusResponse = $input.first().json;

console.log('=== MERGE STATUS ===');
console.log('Input data keys:', Object.keys(inputData));
console.log('Status response full:', JSON.stringify(statusResponse, null, 2));
console.log('Status response type:', typeof statusResponse);

// Process bot status
let botStatus = {};
if (statusResponse && !statusResponse.error) {
  botStatus = statusResponse;
  console.log('Bot Status Retrieved:', botStatus);
} else {
  console.log('Bot Status Error - using defaults');
  botStatus = { error: 'Status unavailable', health: 20, food: 20, position: { x: 0, y: 64, z: 0 } };
}

// Merge input data with bot status
return {
  json: {
    ...inputData,
    playerName: playerData.player_name,
    botStatus,
    worldInfo: worldData,
    source: 'status'
  }
};

// === NORMALIZE INPUT & LOAD HISTORY ===
const inputData = $('Telegram Bot').first().json;

console.log('=== NORMALIZE INPUT ===');
console.log('Raw input data:', JSON.stringify(inputData, null, 2));

let username, message, chatId, source;

// Handle different input sources
if (inputData.source === 'ingame') {
  username = inputData.username;
  message = inputData.message;
  chatId = null;
  source = 'ingame';
  console.log('Processing IN-GAME chat from player:', username);
} else if (inputData.message) {
  username = inputData.message.from?.username || inputData.message.from?.first_name || 'User';
  message = inputData.message.text || '';
  chatId = inputData.message.chat?.id;
  source = 'telegram';
  console.log('Processing TELEGRAM message from user:', username);
} else {
  return { json: { error: 'Unknown input format', rawInput: inputData } };
}

if (!message) {
  return { json: { error: 'No message text', chatId, source } };
}

// === ENTITY NAME NORMALIZATION ===
const entityNames = [
    'iron_golem', 'zombie', 'skeleton', 'creeper', 'spider', 'enderman',
    'villager', 'cow', 'pig', 'sheep', 'chicken', 'horse', 'wolf', 'cat',
    'ocelot', 'bat', 'ghast', 'slime', 'magma_cube', 'witch', 'wither',
    'ender_dragon'
];

function normalizeEntityName(input) {
    if (!input) return input;
    const lowerInput = input.toLowerCase().trim();

    if (entityNames.includes(lowerInput)) {
        return lowerInput;
    }

    const match = entityNames.find(entityName => {
        const cleanEntity = entityName.replace(/_/g, '');
        const cleanInput = lowerInput.replace(/_/g, '');
        return cleanEntity.includes(cleanInput) || cleanInput.includes(cleanEntity);
    });

    return match || input;
}

// Normalize entity names in message (e.g., "attack golem" → "attack iron_golem")
message = message.replace(/\b(golem|zombie|skeleton|creeper|spider|enderman|villager|magma|ender dragon|dragon|iron_golem|magma_cube|ender_dragon)\b/gi, (match) => {
    return normalizeEntityName(match);
});

// Load conversation history and memory
let conversationHistory = [];
let botMemory = '';

try {
  const staticData = $execution.getStaticData('global') || {};
  conversationHistory = staticData.conversationHistory || [];
  botMemory = staticData.botMemory || '';
} catch (e) {
  console.log('Initializing new conversation:', e);
}

conversationHistory.push({
  role: 'user',
  content: `${username}: ${message}`,
  timestamp: Date.now(),
  source: source
});

if (conversationHistory.length > 20) {
  conversationHistory = conversationHistory.slice(-20);
}

try {
  const staticData = $execution.getStaticData('global');
  staticData.conversationHistory = conversationHistory;
  staticData.botMemory = botMemory;
} catch (e) {
  console.log('Could not save conversation history:', e);
}

console.log('Final normalized data:');
console.log('Username:', username);
console.log('Normalized message:', message);
console.log('Source:', source);

return {
  json: {
    username,
    message,
    chatId,
    conversationHistory,
    botMemory,
    timestamp: Date.now(),
    source: source,
    playerName: $input.first().json.playername 
  }
};

